package au.monster.tracker;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.text.InputType;
import android.widget.*;
import android.view.*;
import java.util.*;
import java.time.*;
import java.util.concurrent.*;

/** Cash refunds stay offline. Stripe requests/status use only the authenticated backend. */
public final class RefundActivity extends Activity {
    private Store store;private RefundStore refunds;private Ledger.Event sale;private RefundStore.View state;private LinearLayout body;private TextView status;private boolean busy,dead;private final ExecutorService io=Executors.newSingleThreadExecutor();
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);refunds=new RefundStore(store);String id=getIntent().getStringExtra("saleId");sale=store.snapshot().events().stream().filter(e->e.id().equals(id)).findFirst().orElse(null);if(sale==null){finish();return;}show();}
    @Override protected void onDestroy(){dead=true;io.execute(store::close);io.shutdown();super.onDestroy();}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(0xfff0f5eb);t.setPadding(0,dp(8),0,dp(8));return t;}
    private Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setMinHeight(dp(56));b.setOnClickListener(v->{if(!busy)action.run();});return b;}
    private EditText field(LinearLayout box,String label,String value,boolean money){box.addView(text(label,15));EditText e=new EditText(this);e.setText(value);e.setTextColor(0xfff0f5eb);e.setMinHeight(dp(56));e.setInputType(money?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);box.addView(e);return e;}
    private void error(Throwable e){new AlertDialog.Builder(this).setTitle("Refund not completed").setMessage((e.getMessage()==null?"Check the saved refund status before trying again.":e.getMessage())+"\n\nA saved Stripe request keeps its ID. Retry/check that request rather than creating another refund.").setPositiveButton("OK",null).show();}
    private <T> void job(Callable<T> work,java.util.function.Consumer<T> done){if(busy)return;busy=true;status.setText("Checking / saving…");io.execute(()->{try{T result=work.call();runOnUiThread(()->{if(dead)return;busy=false;done.accept(result);});}catch(Throwable e){runOnUiThread(()->{if(dead)return;busy=false;show();error(e);});}});}
    private void show(){state=refunds.view();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101410);root.setOnApplyWindowInsetsListener((v,insets)->{root.setPadding(dp(16),insets.getSystemWindowInsetTop()+dp(8),dp(16),insets.getSystemWindowInsetBottom()+dp(8));return insets;});setContentView(root);root.requestApplyInsets();root.addView(text("Refunds & returned goods",24));status=text(RefundStore.intent(sale)==null?"Manual refunds work offline":"Stripe refunds require verified online status",14);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(text("Original sale: "+Ledger.money(sale.revenue())+" · "+sale.quantity()+" cans · "+sale.payment()+"\n"+Ledger.displayTime(sale.timestamp())+"\nOriginal card fee remains: "+Ledger.money(sale.fee()),18));body.addView(button(RefundStore.intent(sale)==null?"Record cash/manual card refund":"Request Stripe refund",this::create));if(RefundStore.intent(sale)!=null)body.addView(button("Reconcile Stripe status & Dashboard refunds",this::reconcile));for(var request:state.requests())if(request.saleId().equals(sale.id())){var observation=state.state().latest().get(request.id());body.addView(text(Ledger.money(request.amount())+" · "+(observation==null?"Unresolved request":observation.status())+"\nRequest: "+request.id()+"\n"+request.note()+(observation==null?"":"\nProvider: "+observation.providerId()+"\nVerified/recorded: "+Ledger.displayTime(observation.verifiedAt())+"\nAdditional fee: "+(observation.fee()==null?"not yet known":Ledger.money(observation.fee()))+"\n"+observation.failureReason()),16));if(request.stripe())body.addView(button("Check / retry this same refund",()->check(request)));body.addView(button("Confirm physically received returned cans",()->receive(request)));if(!request.stripe()&&observation!=null&&observation.status().equals("succeeded"))body.addView(button("Correct a mistaken manual refund entry",()->correct(request)));}body.addView(text("Refunds never silently undo the sale or return its original card fee. Only verified successful Stripe refunds reduce net revenue. Pending, failed and canceled states stay visible. A later failure appends a reversal when verified; the verification date is recorded, not an invented bank-processing date. Goods are added only after a separate physical receipt confirmation. Use financial report CSV/PDF to export refunds; ordinary sales/stock CSV retains original sales.",15));body.addView(button("Back to history",this::finish));}
    private PaymentClient api()throws Exception{PaymentSettings settings=new PaymentSettings(this);if(!settings.configured()||!settings.live())throw new IllegalStateException("This is an original live Stripe sale. Connect its original live backend/account before refunding or reconciling. Test mode cannot refund a real sale.");PaymentClient api=new PaymentClient(settings);var config=api.post("/config",new LinkedHashMap<>());if(!FinanceBackup.bool(config,"live"))throw new IllegalStateException("Backend mode differs from this live sale.");return api;}
    private Map<String,Object> body(Refunds.Request request){Map<String,Object> body=new LinkedHashMap<>();body.put("saleId",sale.id());body.put("amount",sale.revenue());body.put("refundId",request.id());body.put("refundAmount",request.amount());body.put("saleRecordedAt",sale.recordedAt());body.put("refundRecordedAt",request.recordedAt());return body;}
    private void create(){long reserved=0;for(var r:state.requests())if(r.saleId().equals(sale.id())){var o=state.state().latest().get(r.id());if(o==null||!Ledger.set("failed","canceled").contains(o.status()))reserved+=r.amount();}long remaining=sale.revenue()-reserved;if(remaining<=0){error(new IllegalArgumentException("No unrefunded amount remains. Check existing requests/status."));return;}boolean stripe=RefundStore.intent(sale)!=null;LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);EditText amount=field(fields,"Refund amount (AUD; max "+Ledger.money(remaining)+")",Ledger.inputMoney(remaining),true),note=field(fields,"Reason / note","",false);EditText fee=stripe?null:field(fields,"Actual additional refund fee (original fee is retained)","0.00",true);String id=Ledger.id();long now=System.currentTimeMillis();long[] actualDate={now};boolean[] unknown={false};if(!stripe){Button[] dateButton={null};Button when=button("Actual refund date/time: "+Ledger.displayTime(actualDate[0]),()->{ZonedDateTime z=Instant.ofEpochMilli(actualDate[0]).atZone(Ledger.PERTH);new DatePickerDialog(this,(picker,y,m,d)->new TimePickerDialog(this,(t,h,min)->{actualDate[0]=LocalDateTime.of(y,m+1,d,h,min).atZone(Ledger.PERTH).toInstant().toEpochMilli();dateButton[0].setText("Actual refund date/time: "+Ledger.displayTime(actualDate[0]));},z.getHour(),z.getMinute(),true).show(),z.getYear(),z.getMonthValue()-1,z.getDayOfMonth()).show();});dateButton[0]=when;fields.addView(when);CheckBox unknownDate=new CheckBox(this);unknownDate.setText("Historical refund date is unknown");unknownDate.setTextColor(0xfff0f5eb);unknownDate.setMinHeight(dp(48));unknownDate.setOnCheckedChangeListener((b,checked)->{unknown[0]=checked;when.setEnabled(!checked);});fields.addView(unknownDate);}ScrollView review=new ScrollView(this);review.addView(fields);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(stripe?"Request real Stripe refund?":"Record refund already paid?").setMessage("The original sale stays in history. No stock will be added. Confirm only the amount you intend to refund; repeated retries use this same ID.").setView(review).setNegativeButton("Cancel",null).setPositiveButton("Confirm refund",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{var request=new Refunds.Request(id,sale.id(),Ledger.cents(amount.getText().toString()),System.currentTimeMillis(),note.getText().toString(),stripe);long extra=stripe?0:Ledger.cents(fee.getText().toString());dialog.dismiss();job(()->{if(stripe){PaymentClient api=api();refunds.request(request);refunds.verified(sale,api.post("/refund",body(request)));}else refunds.manual(request,extra,unknown[0]?null:actualDate[0]);return true;},ok->show());}catch(Exception e){error(e);}}));dialog.show();}
    private void correct(Refunds.Request request){EditText reason=new EditText(this);reason.setHint("Why this recorded refund was a mistake");new AlertDialog.Builder(this).setTitle("Correct bookkeeping entry?").setMessage("Use this only if the manual refund record was incorrect. It appends a correction and does not collect money back from the customer or remove physically received goods. The original stays in history.").setView(reason).setNegativeButton("Keep original",null).setPositiveButton("Append correction",(d,w)->{String note=reason.getText().toString();job(()->{refunds.correctManual(request.id(),note,System.currentTimeMillis());return true;},ok->show());}).show();}
    private void check(Refunds.Request request){job(()->{PaymentClient api=api();refunds.verified(sale,api.post("/refund",body(request)));return true;},ok->show());}
    private void reconcile(){job(()->{var response=api().sale("/reconcile",sale);var payment=Purchases.map(response.get("payment"));if(!Purchases.str(payment,"id").equals(RefundStore.intent(sale))||Purchases.num(payment,"amount")!=sale.revenue()||!FinanceBackup.bool(payment,"live")||!Purchases.str(payment,"status").equals("succeeded"))Purchases.bad("Payment reconciliation does not match the recorded sale.");store.database().beginTransaction();try{for(Object value:Purchases.list(response.get("refunds")))refunds.verified(sale,Purchases.map(value));store.database().setTransactionSuccessful();}finally{store.database().endTransaction();}return true;},ok->{show();status.setText("Payment and refund status verified with Stripe. No new charge was created.");});}
    private void receive(Refunds.Request request){EditText quantity=new EditText(this);quantity.setInputType(InputType.TYPE_CLASS_NUMBER);quantity.setText("1");quantity.setMinHeight(dp(56));String id=Ledger.id();long now=System.currentTimeMillis();AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Returned cans physically received?").setMessage("Enter only cans actually received from this sale, regardless of refund status. No additional purchase cost is created; the original FIFO cost is restored. For damaged returned goods, record the damage separately after receipt. All returns/corrections stay traceable.").setView(quantity).setNegativeButton("Not received",null).setPositiveButton("Confirm received",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{long q=Long.parseLong(quantity.getText().toString());dialog.dismiss();job(()->{refunds.receive(id,request.id(),q,now);return true;},ok->show());}catch(Exception e){error(e);}}));dialog.show();}
}
